import { budgetRemaining, categoryRollups, fixedVariableTotals, formatMoney, hourlyGross, netWorth, parseMoney, paycheckEstimate, reconciledPay, retirementProjection, savingsProjection, savingsRate } from './calculations.js';
import { mountEcosystemProfileMenu } from '../shared/identity.js?v=3';

const SETTINGS_KEY='money-settings-v1';
const THEMES=['classic','ledger','clear','vault','market'];
const DEFAULT_SETTINGS={theme:'classic',density:'comfortable',onboardingDismissed:false};
const NAV_GROUPS={overview:['overview'],budget:['budget','transactions','bills'],plan:['savings','retirement'],more:['earnings','assets','reports']};
const NAV_LABELS={budget:'Monthly plan',transactions:'Transactions',bills:'Bills',savings:'Savings',retirement:'Retirement',earnings:'Earnings',assets:'Assets & net worth',reports:'Reports'};
const TABLES={categories:'money_categories',budgets:'money_monthly_budgets',assets:'money_assets',incomeSources:'money_income_sources',workEntries:'money_work_entries',paychecks:'money_paychecks',transactions:'money_transactions',bills:'money_bills',savingsGoals:'money_savings_goals',contributions:'money_savings_contributions',retirementProfiles:'money_retirement_profiles',retirementAccounts:'money_retirement_accounts',allocations:'money_investment_allocations',snapshots:'money_net_worth_snapshots'};
const client=window.AppAuth?.client||null;
const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
let currentUser=null,settings=loadSettings(),activeView='overview',onboardingStep=1;
let state=Object.fromEntries(Object.keys(TABLES).map((key)=>[key,[]]));
let loadedUserId=null,sessionLoadPromise=null;

initialize();

async function initialize(){
  applySettings();enhanceRetirementDisclosure();bindEvents();setDefaultDates();updateIncomeSourceExperience();updateOnboardingFields();
  if(!client)return redirectToLogin();
  client.auth.onAuthStateChange((_event,session)=>setTimeout(()=>applySession(session),0));
  const{data,error}=await client.auth.getSession();if(error||!data.session)return redirectToLogin();await applySession(data.session);
}

async function applySession(session){
  if(!session?.user?.email_confirmed_at){if(session?.user)await client.auth.signOut();return redirectToLogin()}
  if(loadedUserId===session.user.id)return;
  if(sessionLoadPromise)return sessionLoadPromise;
  currentUser=session.user;setCloud('Loading private records…');void mountEcosystemProfileMenu({client,user:currentUser,appId:'money',onSettings:openSettings,onSignOut:()=>client.auth.signOut()});
  sessionLoadPromise=(async()=>{try{await loadState();if(!state.categories.length)await seedCategories();loadedUserId=currentUser.id;document.body.classList.remove('auth-pending');setCloud('Cloud verified');hideLoadNotice();populateControls();applyRoute();renderAll();maybeOpenOnboarding()}
  catch(error){loadedUserId=null;document.body.classList.remove('auth-pending');setCloud('Cloud load failed',true);showLoadError(error)}})();
  try{await sessionLoadPromise}finally{sessionLoadPromise=null}
}

function redirectToLogin(){location.replace(`${location.origin}/account/?returnTo=/money/`)}
async function loadState(){const results=await Promise.all(Object.values(TABLES).map((table)=>client.from(table).select('*')));const error=results.find((item)=>item.error)?.error;if(error)throw error;Object.keys(TABLES).forEach((key,index)=>{state[key]=results[index].data||[]})}
async function saveRow(key,row){const record={...row,user_id:currentUser.id};const{data,error}=await client.from(TABLES[key]).upsert(record,{onConflict:'user_id,id'}).select().single();if(error)throw error;const index=state[key].findIndex((item)=>item.id===data.id);if(index>=0)state[key][index]=data;else state[key].push(data);return data}
async function removeRow(key,id){const{error}=await client.from(TABLES[key]).delete().eq('user_id',currentUser.id).eq('id',id);if(error)throw error;state[key]=state[key].filter((item)=>item.id!==id)}

async function seedCategories(){
  const food=crypto.randomUUID(),transport=crypto.randomUUID(),housing=crypto.randomUUID(),income=crypto.randomUUID();
  const rows=[
    {id:food,name:'Food',parent_id:null,category_type:'expense',classification:'variable',sort_order:10},{id:crypto.randomUUID(),name:'Groceries',parent_id:food,category_type:'expense',classification:null,sort_order:11},{id:crypto.randomUUID(),name:'Restaurants',parent_id:food,category_type:'expense',classification:null,sort_order:12},{id:crypto.randomUUID(),name:'Coffee',parent_id:food,category_type:'expense',classification:null,sort_order:13},
    {id:transport,name:'Transportation',parent_id:null,category_type:'expense',classification:'variable',sort_order:20},{id:crypto.randomUUID(),name:'Gas',parent_id:transport,category_type:'expense',classification:null,sort_order:21},{id:crypto.randomUUID(),name:'Maintenance',parent_id:transport,category_type:'expense',classification:null,sort_order:22},{id:crypto.randomUUID(),name:'Parking',parent_id:transport,category_type:'expense',classification:null,sort_order:23},
    {id:housing,name:'Housing',parent_id:null,category_type:'expense',classification:'fixed',sort_order:30},{id:crypto.randomUUID(),name:'Rent / Mortgage',parent_id:housing,category_type:'expense',classification:null,sort_order:31},{id:crypto.randomUUID(),name:'Utilities',parent_id:housing,category_type:'expense',classification:null,sort_order:32},
    {id:income,name:'Pay & Earnings',parent_id:null,category_type:'income',classification:null,sort_order:100}
  ].map((row)=>({...row,user_id:currentUser.id,active:true}));
  const{data,error}=await client.from(TABLES.categories).insert(rows).select();if(error)throw error;state.categories=data;
}

function bindEvents(){
  $$('[data-view-target]').forEach((button)=>button.addEventListener('click',()=>showView(button.dataset.viewTarget)));
  $$('[data-quick]').forEach((button)=>button.addEventListener('click',()=>runQuickAction(button.dataset.quick)));
  window.addEventListener('hashchange',applyRoute);
  $('#closeSettings').addEventListener('click',()=>$('#settingsModal').close());
  $$('[data-settings-open]').forEach((button)=>button.addEventListener('click',()=>showSettingsPanel(button.dataset.settingsOpen)));$$('[data-settings-back]').forEach((button)=>button.addEventListener('click',()=>showSettingsPanel('main')));
  $('#settingsModal').addEventListener('close',()=>showSettingsPanel('main',false));$('#settingsModal').addEventListener('change',saveSettingsControls);$('#signOut').addEventListener('click',()=>client.auth.signOut());$('#resetMoney').addEventListener('click',resetMoney);
  $('#retryLoad').addEventListener('click',()=>applySession(currentUser?{user:currentUser}:null));
  $('#overviewMonth').addEventListener('change',renderOverview);$('#budgetMonth').addEventListener('change',async()=>{await ensureBudgetMonth($('#budgetMonth').value);renderBudget()});
  $('#categoryForm').addEventListener('submit',saveCategory);$('#categoryForm').addEventListener('reset',()=>setTimeout(()=>{$('#categoryId').value=''},0));
  $('#transactionForm').addEventListener('submit',saveTransaction);$('#transactionForm').addEventListener('reset',()=>setTimeout(()=>{$('#transactionId').value=''},0));['transactionSearch','transactionFilter','transactionSort'].forEach((id)=>$(`#${id}`).addEventListener('input',renderTransactions));
  $('#billForm').addEventListener('submit',saveBill);$('#billForm').addEventListener('reset',()=>setTimeout(()=>{$('#billId').value='';$('#billActive').checked=true},0));
  $('#incomeSourceForm').addEventListener('submit',saveIncomeSource);['incomeSourceType','incomeHourlyRate','incomeExpectedHours','incomeSalary','incomeFrequency'].forEach((id)=>$(`#${id}`).addEventListener('input',updateIncomeSourceExperience));$('#workForm').addEventListener('submit',saveWork);$('#paycheckForm').addEventListener('submit',savePaycheck);['workSource','workRegular','workOvertime'].forEach((id)=>$(`#${id}`).addEventListener('input',updateWorkEstimate));['payGross','payPreTax','payRetirement','payBenefits','payFederalRate','payStateRate','payPostTax'].forEach((id)=>$(`#${id}`).addEventListener('input',updatePayEstimate));
  $('#savingsForm').addEventListener('submit',saveSavingsGoal);$('#contributionForm').addEventListener('submit',saveContribution);$('#retirementForm').addEventListener('submit',saveRetirementProfile);$('#retirementAccountForm').addEventListener('submit',saveRetirementAccount);$('#allocationForm').addEventListener('submit',saveAllocation);$$('[data-ret-scenario]').forEach((button)=>button.addEventListener('click',()=>applyRetirementScenario(button.dataset.retScenario)));
  $('#assetForm').addEventListener('submit',saveAsset);$('#snapshotNetWorth').addEventListener('click',saveNetWorthSnapshot);$('#reportRange').addEventListener('change',renderReports);['reportStart','reportEnd'].forEach(id=>$(`#${id}`).addEventListener('change',renderReports));
  document.addEventListener('change',handleDelegatedChange);document.addEventListener('click',handleDelegatedClick);
  $('#onboardingNext').addEventListener('click',advanceOnboarding);$('#onboardingBack').addEventListener('click',()=>showOnboardingStep(onboardingStep-1));$('#onboardingSkip').addEventListener('click',dismissOnboarding);$('#onboardingModal').addEventListener('close',()=>{if(!settings.onboardingDismissed){settings.onboardingDismissed=true;persistSettings()}});$$('input[name="onboarding-income-type"]').forEach((input)=>input.addEventListener('change',updateOnboardingFields));['onboardingIncomeAmount','onboardingHours'].forEach((id)=>$(`#${id}`).addEventListener('input',updateOnboardingPreview));
}

function navRoot(view){return Object.entries(NAV_GROUPS).find(([,views])=>views.includes(view))?.[0]||'overview'}
function renderSectionNav(){const root=navRoot(activeView),views=NAV_GROUPS[root];$('#sectionNav').hidden=root==='overview';$('#sectionNav').innerHTML=root==='overview'?'':`<span>${root==='budget'?'Everyday money':root==='plan'?'Plan ahead':'More tools'}</span>${views.map((view)=>`<button class="${view===activeView?'active':''}" data-section-view="${view}">${NAV_LABELS[view]}</button>`).join('')}`;$$('[data-section-view]',$('#sectionNav')).forEach((button)=>button.addEventListener('click',()=>showView(button.dataset.sectionView)))}
function showView(view,updateHash=true){activeView=view;$$('.view').forEach((item)=>item.classList.toggle('active',item.dataset.view===view));const root=navRoot(view);$$('.nav-item').forEach((item)=>item.classList.toggle('active',item.dataset.navRoot===root));renderSectionNav();if(updateHash&&location.hash!==`#${view}`)history.replaceState(null,'',`#${view}`);renderAll();window.scrollTo({top:0,behavior:'smooth'})}
function applyRoute(){const view=location.hash.slice(1);showView(['overview','budget','transactions','bills','earnings','savings','retirement','assets','reports'].includes(view)?view:'overview',false)}
function renderAll(){populateControls();renderOverview();renderBudget();renderTransactions();renderBills();renderEarnings();renderSavings();renderRetirement();renderAssets();renderReports()}

function populateControls(){
  const parents=state.categories.filter((item)=>!item.parent_id).sort(sortOrder);$('#categoryParent').innerHTML='<option value="">Top-level category</option>'+parents.map((item)=>`<option value="${item.id}">${escapeHtml(item.name)}</option>`).join('');
  const categoryOptions=state.categories.filter((item)=>item.active).sort(sortOrder).map((item)=>`<option value="${item.id}">${item.parent_id?'— ':''}${escapeHtml(item.name)}</option>`).join('');['transactionCategory','billCategory'].forEach((id)=>{const value=$(`#${id}`).value;$(`#${id}`).innerHTML=`<option value="">Uncategorized</option>${categoryOptions}`;$(`#${id}`).value=value});
  const assetOptions=state.assets.filter((item)=>item.active).map((item)=>`<option value="${item.id}">${escapeHtml(item.name)}</option>`).join('');const assetValue=$('#transactionAsset').value;$('#transactionAsset').innerHTML=`<option value="">None</option>${assetOptions}`;$('#transactionAsset').value=assetValue;
  const sourceOptions=state.incomeSources.filter((item)=>item.active).map((item)=>`<option value="${item.id}">${escapeHtml(item.name)}</option>`).join('');['transactionIncomeSource','workSource','paycheckSource'].forEach((id)=>{const value=$(`#${id}`).value;$(`#${id}`).innerHTML=`<option value="">${id==='transactionIncomeSource'?'None':'Choose source'}</option>${sourceOptions}`;$(`#${id}`).value=value});
  const goalValue=$('#contributionGoal').value;$('#contributionGoal').innerHTML='<option value="">Choose goal</option>'+state.savingsGoals.filter(x=>x.active).map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('');$('#contributionGoal').value=goalValue;
  const accountValue=$('#allocationAccount').value;$('#allocationAccount').innerHTML='<option value="">Choose account</option>'+state.retirementAccounts.filter(x=>x.active).map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('');$('#allocationAccount').value=accountValue;
}

function monthKey(date=new Date()){return date.toISOString().slice(0,7)}
function monthBounds(month){const start=`${month}-01`;const date=new Date(`${start}T00:00:00Z`);date.setUTCMonth(date.getUTCMonth()+1);return{start,end:date.toISOString().slice(0,10)}}
function isExpectedOnlyTransaction(item){return item.paycheck_id&&state.paychecks.some(paycheck=>paycheck.id===item.paycheck_id&&paycheck.status!=='reconciled')}
function monthlyTransactions(month){const{start,end}=monthBounds(month);return state.transactions.filter((item)=>item.transaction_date>=start&&item.transaction_date<end&&!isExpectedOnlyTransaction(item))}
function renderOverview(){
  const month=$('#overviewMonth').value||monthKey(),transactions=monthlyTransactions(month),income=sum(transactions.filter((x)=>x.transaction_type==='income'),'amount_minor'),spending=sum(transactions.filter((x)=>x.transaction_type==='expense'),'amount_minor'),left=income-spending;
  const paychecks=state.paychecks.filter((item)=>item.pay_date.startsWith(month)),takeHome=paychecks.filter(x=>x.status==='reconciled').reduce((total,item)=>total+reconciledPay(item).netMinor,0),expected=expectedMonthlyIncome(),savedThisMonth=sum(state.contributions.filter(x=>x.contribution_date.startsWith(month)),'amount_minor'),savings=state.savingsGoals.reduce((total,item)=>total+Number(item.current_minor),0),worth=netWorth(state.assets),budgets=state.budgets.filter((item)=>String(item.budget_month).startsWith(month)),budgeted=sum(budgets,'amount_minor');
  const monthName=new Date(`${month}-01T00:00:00Z`).toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'});
  $('#overviewHero').innerHTML=`<div class="month-story-heading"><span>${escapeHtml(monthName)}</span><small>${expected?`${formatMoney(expected)} expected before deductions`:'Add a job to see expected income'}</small></div><div class="story-grid">${storyMetric('Received',income,'Money recorded as income','income')}${storyMetric('Spent',spending,'Expenses recorded this month','expense')}${storyMetric('Left',left,'Received minus spending','left')}${storyMetric('Saved',savedThisMonth,savedThisMonth?'Contributions this month':'Record a contribution','saved')}</div>`;
  $('#overviewSecondaryStats').innerHTML=[['Take-home received',takeHome,takeHome?'From reconciled paychecks':'No actual paycheck yet'],['Budget used',spending,budgeted?`${Math.round(spending/budgeted*100)}% of ${formatMoney(budgeted)}`:'Set a monthly budget'],['Total savings',savings,`${savingsRate(income,spending)}% monthly savings rate`],['Net worth',worth.netWorthMinor,`${formatMoney(worth.assetsMinor)} in assets`]].map(([label,value,detail])=>`<article><span>${label}</span><strong>${formatMoney(value)}</strong><small>${detail}</small></article>`).join('');renderCashflowChart(month);
  const upcoming=[...state.bills].filter((item)=>item.active).sort((a,b)=>a.next_due_date.localeCompare(b.next_due_date)).slice(0,5);$('#upcomingBills').innerHTML=upcoming.length?upcoming.map(billPreviewRow).join(''):friendlyEmpty('No bills on the horizon.','Add a recurring bill so upcoming payments appear here.','Add bill','bills');
  const rollups=categoryRollups(state.categories,state.transactions,month),budgetMap=new Map(budgets.map(x=>[x.category_id,x]));const top=state.categories.filter((item)=>!item.parent_id&&item.category_type==='expense').sort((a,b)=>(rollups.get(b.id)||0)-(rollups.get(a.id)||0)).slice(0,5);$('#overviewBudget').innerHTML=top.length?top.map((item)=>overviewBudgetRow(item,rollups.get(item.id)||0,Number(budgetMap.get(item.id)?.amount_minor||0))).join(''):friendlyEmpty('Your budget is ready when you are.','Add a category and monthly amount to start tracking progress.','Build a budget','budget');
  const recent=[...transactions].sort((a,b)=>b.transaction_date.localeCompare(a.transaction_date)).slice(0,5);$('#recentTransactions').innerHTML=recent.length?recent.map(transactionRow).join(''):friendlyEmpty('No activity this month.','Add income or an expense to start your monthly picture.','Add an expense','transactions');
}
function storyMetric(label,value,detail,tone){return`<article class="story-metric ${tone}"><span>${label}</span><strong>${formatMoney(value)}</strong><small>${detail}</small></article>`}
function billPreviewRow(item){const date=new Date(`${item.next_due_date}T00:00:00Z`);return`<article class="bill-preview"><time datetime="${item.next_due_date}"><b>${date.toLocaleDateString('en-US',{month:'short',timeZone:'UTC'})}</b><strong>${date.getUTCDate()}</strong></time><div><h3>${escapeHtml(item.name)}</h3><p>${humanFrequency(item.frequency)}</p></div><strong>${formatMoney(item.amount_minor)}</strong></article>`}
function overviewBudgetRow(item,spent,budget){const progress=budget?Math.min(100,Math.round(spent/budget*100)):0;return`<button class="overview-budget-row" data-go-to="budget"><span class="category-icon">${categoryIcon(item.name)}</span><span><b>${escapeHtml(item.name)}</b><small>${budget?`${formatMoney(spent)} of ${formatMoney(budget)}`:`${formatMoney(spent)} spent · add a budget`}</small><i><em style="width:${progress}%"></em></i></span><strong>${budget?`${progress}%`:'—'}</strong></button>`}
function renderCashflowChart(month){const months=[];const date=new Date(`${month}-01T00:00:00Z`);for(let i=5;i>=0;i--){const d=new Date(date);d.setUTCMonth(d.getUTCMonth()-i);const key=d.toISOString().slice(0,7),items=monthlyTransactions(key);months.push({label:d.toLocaleDateString('en-US',{month:'short',timeZone:'UTC'}),income:sum(items.filter(x=>x.transaction_type==='income'),'amount_minor'),expense:sum(items.filter(x=>x.transaction_type==='expense'),'amount_minor')})}const max=Math.max(1,...months.flatMap(x=>[x.income,x.expense]));$('#cashflowChart').innerHTML=months.flatMap(item=>[{label:`${item.label} in`,value:item.income},{label:`${item.label} out`,value:item.expense}]).map(item=>bar(item.label,item.value,max)).join('')}

async function ensureBudgetMonth(month){if(state.budgets.some((item)=>String(item.budget_month).startsWith(month)))return;const prior=state.budgets.filter((item)=>String(item.budget_month).slice(0,7)<month).sort((a,b)=>String(b.budget_month).localeCompare(String(a.budget_month)));if(!prior.length)return;const latest=String(prior[0].budget_month).slice(0,7),copies=prior.filter((item)=>String(item.budget_month).startsWith(latest)).map((item)=>({id:crypto.randomUUID(),user_id:currentUser.id,category_id:item.category_id,budget_month:`${month}-01`,amount_minor:item.amount_minor}));if(!copies.length)return;const{data,error}=await client.from(TABLES.budgets).insert(copies).select();if(error)throw error;state.budgets.push(...data)}
function renderBudget(){
  const month=$('#budgetMonth').value||monthKey(),rollups=categoryRollups(state.categories,state.transactions,month),budgetMap=new Map(state.budgets.filter((item)=>String(item.budget_month).startsWith(month)).map((item)=>[item.category_id,item]));
  const parents=state.categories.filter((item)=>!item.parent_id&&item.category_type==='expense').sort(sortOrder);$('#budgetList').innerHTML=parents.length?parents.map((parent)=>{const children=state.categories.filter((item)=>item.parent_id===parent.id).sort(sortOrder);return`<section class="budget-group">${budgetRow(parent,budgetMap.get(parent.id),rollups.get(parent.id)||0,true)}${children.map((child)=>budgetRow(child,budgetMap.get(child.id),rollups.get(child.id)||0,false)).join('')}</section>`}).join(''):empty('Create an expense category to begin.');
}
function budgetRow(category,budget,spent,isParent){const amount=Number(budget?.amount_minor||0),remaining=budgetRemaining(amount,spent),progress=amount?Math.min(100,Math.round(spent/amount*100)):0;return`<div class="${isParent?'budget-parent':'budget-child'}"><div class="budget-identity">${isParent?`<span class="category-icon">${categoryIcon(category.name)}</span>`:''}<span><strong>${escapeHtml(category.name)}</strong>${isParent?`<small>${formatMoney(spent)} of ${formatMoney(amount)} · ${formatMoney(remaining)} left</small><div class="progress" aria-label="${progress}% of budget used"><i style="width:${progress}%"></i></div>`:''}</span></div><label class="budget-cell">Monthly budget<input class="budget-input" data-budget-category="${category.id}" value="${(amount/100).toFixed(2)}" inputmode="decimal"></label><span class="budget-cell spent">Spent<b>${formatMoney(spent)}</b></span><span class="budget-cell remaining">Left<b>${formatMoney(remaining)}</b></span><span class="row-actions"><button class="small-action" data-action="move-category-up" data-id="${category.id}" aria-label="Move ${escapeHtml(category.name)} up">↑</button><button class="small-action" data-action="edit-category" data-id="${category.id}">Edit</button><button class="small-action danger" data-action="delete-category" data-id="${category.id}">Delete</button></span></div>`}

function renderTransactions(){const search=$('#transactionSearch').value.trim().toLowerCase(),filter=$('#transactionFilter').value,sort=$('#transactionSort').value;let items=state.transactions.filter((item)=>!isExpectedOnlyTransaction(item)&&(filter==='all'||item.transaction_type===filter)&&(!search||`${item.description} ${item.notes}`.toLowerCase().includes(search)));items.sort(sort==='oldest'?(a,b)=>a.transaction_date.localeCompare(b.transaction_date):sort==='largest'?(a,b)=>b.amount_minor-a.amount_minor:sort==='smallest'?(a,b)=>a.amount_minor-b.amount_minor:(a,b)=>b.transaction_date.localeCompare(a.transaction_date));$('#transactionList').innerHTML=items.length?items.map(transactionRow).join(''):friendlyEmpty('No transactions match.','Record income or an expense, or adjust your filters.','Add an expense','transactions')}
function transactionRow(item){const category=state.categories.find((x)=>x.id===item.category_id),asset=state.assets.find((x)=>x.id===item.asset_id);return`<article class="list-row"><div><h3>${escapeHtml(item.description)}</h3><p>${item.transaction_date}${category?` · ${escapeHtml(category.name)}`:''}${asset?` · ${escapeHtml(asset.name)}`:''}</p></div><strong class="money-value ${item.transaction_type}">${item.transaction_type==='expense'?'−':'+'}${formatMoney(item.amount_minor)}</strong><span class="row-actions"><button class="small-action" data-action="edit-transaction" data-id="${item.id}">Edit</button><button class="small-action danger" data-action="delete-transaction" data-id="${item.id}">Delete</button></span></article>`}

function renderBills(){const active=state.bills.filter((item)=>item.active).sort((a,b)=>a.next_due_date.localeCompare(b.next_due_date));$('#billCommitment').textContent=`${formatMoney(active.reduce((sum,item)=>sum+monthlyBillAmount(item),0))} / month`;$('#billList').innerHTML=state.bills.length?[...state.bills].sort((a,b)=>a.next_due_date.localeCompare(b.next_due_date)).map((item)=>{const date=new Date(`${item.next_due_date}T00:00:00Z`);return`<article class="bill-card${item.active?'':' inactive'}"><time datetime="${item.next_due_date}"><b>${date.toLocaleDateString('en-US',{month:'short',timeZone:'UTC'})}</b><strong>${date.getUTCDate()}</strong></time><div><h3>${escapeHtml(item.name)}</h3><p>${humanFrequency(item.frequency)} · ${item.classification}${item.active?'':' · inactive'}</p></div><strong>${formatMoney(item.amount_minor)}</strong><span class="row-actions"><button class="small-action" data-action="record-bill" data-id="${item.id}">Record paid</button><button class="small-action" data-action="edit-bill" data-id="${item.id}">Edit</button><button class="small-action danger" data-action="delete-bill" data-id="${item.id}">Delete</button></span></article>`}).join(''):friendlyEmpty('No recurring bills yet.','Add rent, utilities, subscriptions, or anything else you want to see coming.','Add your first bill','bills')}

function renderEarnings(){
  const expected=expectedMonthlyIncome(),month=monthKey(),received=sum(monthlyTransactions(month).filter(x=>x.transaction_type==='income'),'amount_minor');$('#earningsSummary').innerHTML=`<article><span>Expected</span><strong>${formatMoney(expected)}</strong><small>Monthly gross from active sources</small></article><article><span>Received</span><strong>${formatMoney(received)}</strong><small>Income actually recorded this month</small></article><article><span>Difference</span><strong>${formatMoney(received-expected)}</strong><small>Received minus expected</small></article>`;
  $('#incomeSourceList').innerHTML=state.incomeSources.length?state.incomeSources.map(incomeSourceCard).join(''):friendlyEmpty('Add your job or another source of income.','You’ll immediately see an understandable monthly and paycheck estimate.','Add income','earnings');
  const work=state.workEntries.map((item)=>({date:item.work_date,markup:`<article class="list-row"><div><h3>${escapeHtml(sourceName(item.income_source_id))} work</h3><p>${item.work_date} · ${formatHours(item.regular_minutes+item.overtime_minutes)}${item.overtime_minutes?` (${formatHours(item.overtime_minutes)} OT)`:''}</p></div><strong>${formatMoney(item.estimated_gross_minor)} est.</strong><span class="row-actions"><button class="small-action danger" data-action="delete-work" data-id="${item.id}">Delete</button></span></article>`}));
  const pay=state.paychecks.map((item)=>{const reconciled=reconciledPay(item);return{date:item.pay_date,markup:`<article class="list-row"><div><h3>${escapeHtml(sourceName(item.income_source_id))} paycheck</h3><p>${item.period_start} – ${item.period_end} · ${item.status==='reconciled'?'Received':'Expected'}</p></div><strong>${formatMoney(reconciled.netMinor)} ${item.status==='reconciled'?'received':'expected'}</strong><span class="row-actions"><button class="small-action" data-action="edit-paycheck" data-id="${item.id}">View details</button><button class="small-action danger" data-action="delete-paycheck" data-id="${item.id}">Delete</button></span></article>`}});$('#earningsList').innerHTML=[...work,...pay].sort((a,b)=>b.date.localeCompare(a.date)).map((x)=>x.markup).join('')||friendlyEmpty('No hours or paychecks yet.','Hourly work and actual pay will appear here when you choose to track them.','Track earnings','earnings');updateIncomeSourceExperience();updateWorkEstimate();updatePayEstimate();
}
function incomeSourceCard(item){const monthly=sourceExpectedMonthly(item),paycheck=sourceExpectedPaycheck(item),type=item.income_type.replace('_',' ');let primary='',detail='';if(item.hourly_rate_minor!=null){primary=`${formatMoney(item.hourly_rate_minor)} / hour`;detail=item.standard_weekly_minutes?`${formatHours(item.standard_weekly_minutes)} expected weekly · ≈ ${formatMoney(monthly)} / month gross`:'Add expected hours or track worked hours to estimate income.'}else if(item.annual_salary_minor!=null){primary=`${formatMoney(item.annual_salary_minor)} / year`;detail=`≈ ${formatMoney(monthly)} / month gross${paycheck?` · ≈ ${formatMoney(paycheck)} per paycheck`:''}`}else{primary='Amount not set';detail='Add an expected amount when you are ready.'}return`<article class="income-card"><div class="income-card-top"><span class="category-icon">${item.hourly_rate_minor!=null?'⏱':'◎'}</span><span><small>${escapeHtml(type)} · ${humanFrequency(item.pay_frequency)}</small><h3>${escapeHtml(item.name)}</h3></span><i>${item.active?'Active':'Inactive'}</i></div><strong>${primary}</strong><p>${detail}</p><div class="row-actions"><button class="small-action" data-action="edit-income-source" data-id="${item.id}">View details</button><button class="small-action danger" data-action="delete-income-source" data-id="${item.id}">Delete</button></div></article>`}

function renderSavings(){const goal=state.savingsGoals[0];if(goal){const points=savingsProjection(goal.current_minor,goal.monthly_contribution_minor,24);$('#savingsChart').innerHTML=lineChart(points.map((p)=>p.valueMinor))}else $('#savingsChart').innerHTML=friendlyEmpty('No projection yet.','Add a goal and optional monthly contribution to explore a scenario.','Add a goal','savings');$('#savingsList').innerHTML=state.savingsGoals.length?state.savingsGoals.map((item)=>{const progress=Math.min(100,Math.round(item.current_minor/item.target_minor*100)),remaining=Math.max(0,item.target_minor-item.current_minor),months=item.monthly_contribution_minor?Math.ceil(remaining/item.monthly_contribution_minor):null;return`<article class="savings-card"><div class="savings-ring" style="--progress:${progress}%"><strong>${progress}%</strong></div><div><p class="eyebrow">Savings goal</p><h3>${escapeHtml(item.name)}</h3><strong>${formatMoney(item.current_minor)} <small>of ${formatMoney(item.target_minor)}</small></strong><div class="progress"><i style="width:${progress}%"></i></div><p>${formatMoney(remaining)} to go${months==null?'':` · about ${months} months`}</p><span class="row-actions"><button class="small-action" data-action="edit-savings" data-id="${item.id}">Edit goal</button><button class="small-action danger" data-action="delete-savings" data-id="${item.id}">Delete</button></span></div></article>`}).join(''):friendlyEmpty('What are you saving for?','Create a goal and watch each contribution move you closer.','Add your first goal','savings');$('#contributionList').innerHTML=state.contributions.length?[...state.contributions].sort((a,b)=>b.contribution_date.localeCompare(a.contribution_date)).slice(0,10).map(item=>simpleRow(state.savingsGoals.find(x=>x.id===item.savings_goal_id)?.name||'Savings goal',`${item.contribution_date}${item.notes?` · ${item.notes}`:''}`,formatMoney(item.amount_minor))).join(''):empty('Contributions will appear here.')}

function renderRetirement(){const profile=state.retirementProfiles[0];if(profile)fillRetirementForm(profile,false);const input=retirementInput();const result=retirementProjection(input);$('#retirementStats').innerHTML=[['Projected',result.balanceMinor],['Your contributions',result.userContributionsMinor],['Employer contributions',result.employerContributionsMinor],['Estimated growth',result.growthMinor]].map(([label,value])=>`<div class="mini-stat"><span>${label}</span><strong>${formatMoney(value)}</strong></div>`).join('');$('#retirementChart').innerHTML=lineChart(result.points.map((p)=>p.balanceMinor));$('#retirementAccounts').innerHTML=state.retirementAccounts.length?state.retirementAccounts.map((item)=>`<article class="list-row"><div><h3>${escapeHtml(item.name)}</h3><p>${escapeHtml(item.account_type)}</p></div><strong>${formatMoney(item.current_balance_minor)}</strong><span class="row-actions"><button class="small-action danger" data-action="delete-retirement-account" data-id="${item.id}">Delete</button></span></article>`).join(''):empty('No retirement accounts yet.');$('#allocationList').innerHTML=state.allocations.length?state.allocations.map(item=>`<article class="list-row"><div><h3>${escapeHtml(item.asset_class)}</h3><p>${escapeHtml(state.retirementAccounts.find(x=>x.id===item.retirement_account_id)?.name||'Account')} · current ${item.current_basis_points/100}% · target ${item.target_basis_points/100}%</p></div><span class="row-actions"><button class="small-action danger" data-action="delete-allocation" data-id="${item.id}">Delete</button></span></article>`).join(''):empty('No allocation targets yet.')}

function renderAssets(){const worth=netWorth(state.assets);$('#netWorthStats').innerHTML=[['Assets',worth.assetsMinor,'What you own'],['Liabilities',worth.liabilitiesMinor,'What you owe'],['Net worth',worth.netWorthMinor,'Assets minus liabilities'],['Ownership costs',sum(state.transactions.filter((item)=>item.asset_id&&item.transaction_type==='expense'),'amount_minor'),'Asset-linked expenses']].map(([a,b,c],i)=>statCard(a,b,c,i===2)).join('');$('#assetList').innerHTML=state.assets.length?state.assets.map((item)=>`<article class="list-row"><div><h3>${escapeHtml(item.name)}</h3><p>${item.asset_group.replaceAll('_',' ')} · ${escapeHtml(item.asset_type)}</p></div><strong>${formatMoney(item.current_value_minor)}</strong><span class="row-actions"><button class="small-action" data-action="edit-asset" data-id="${item.id}">Edit</button><button class="small-action danger" data-action="delete-asset" data-id="${item.id}">Delete</button></span></article>`).join(''):friendlyEmpty('Net worth is optional.','Add an account, property, or liability whenever this view becomes useful to you.','Add an asset','assets');const snapshots=[...state.snapshots].sort((a,b)=>a.snapshot_date.localeCompare(b.snapshot_date));$('#netWorthChart').innerHTML=snapshots.length>1?lineChart(snapshots.map((item)=>item.net_worth_minor)):empty('Save snapshots over time to build net-worth history.')}

function renderReports(){const range=$('#reportRange').value;$('#customReportDates').hidden=range!=='custom';const{start,end}=reportBounds(range),transactions=state.transactions.filter((item)=>item.transaction_date>=start&&item.transaction_date<=end&&!isExpectedOnlyTransaction(item)),income=sum(transactions.filter(x=>x.transaction_type==='income'),'amount_minor'),expense=sum(transactions.filter(x=>x.transaction_type==='expense'),'amount_minor'),fixed=fixedVariableTotals(transactions,state.categories),paychecks=state.paychecks.filter((item)=>item.pay_date>=start&&item.pay_date<=end),work=state.workEntries.filter((item)=>item.work_date>=start&&item.work_date<=end);const gross=paychecks.reduce((s,p)=>s+reconciledPay(p).grossMinor,0),net=paychecks.reduce((s,p)=>s+reconciledPay(p).netMinor,0),withholding=paychecks.reduce((s,p)=>s+Number(p.actual_federal_minor||p.estimated_federal_minor||0)+Number(p.actual_state_minor||p.estimated_state_minor||0)+Number(p.actual_social_security_minor||p.estimated_social_security_minor||0)+Number(p.actual_medicare_minor||p.estimated_medicare_minor||0),0),retirement=paychecks.reduce((s,p)=>s+Number(p.actual_retirement_minor||p.estimated_retirement_minor||0)+Number(p.employer_retirement_minor||0),0);$('#reportStats').innerHTML=[['Income',income,'Transactions'],['Expenses',expense,`${savingsRate(income,expense)}% savings rate`],['Gross pay',gross,`${formatHours(work.reduce((s,w)=>s+w.regular_minutes+w.overtime_minutes,0))} worked`],['Net pay',net,`${formatMoney(withholding)} withheld`],['Fixed',fixed.fixedMinor,'Fixed spending'],['Variable',fixed.variableMinor,'Variable spending'],['Retirement',retirement,'Employee + employer'],['Recurring',state.bills.filter(b=>b.active).reduce((s,b)=>s+monthlyBillAmount(b),0),'Monthly equivalent']].map(([a,b,c])=>statCard(a,b,c)).join('');const categoryTotals=new Map();transactions.filter(x=>x.transaction_type==='expense').forEach(x=>categoryTotals.set(x.category_id,(categoryTotals.get(x.category_id)||0)+Number(x.amount_minor)));const categories=[...categoryTotals].map(([id,value])=>({label:state.categories.find(x=>x.id===id)?.name||'Uncategorized',value})).sort((a,b)=>b.value-a.value);const max=Math.max(1,...categories.map(x=>x.value));$('#reportCategoryChart').innerHTML=categories.length?categories.slice(0,8).map(x=>bar(x.label,x.value,max)).join(''):empty('No spending in this range.');const assetCosts=new Map();transactions.filter(x=>x.asset_id&&x.transaction_type==='expense').forEach(x=>assetCosts.set(x.asset_id,(assetCosts.get(x.asset_id)||0)+Number(x.amount_minor)));$('#reportDetails').innerHTML=[...assetCosts].map(([id,value])=>simpleRow(state.assets.find(x=>x.id===id)?.name||'Asset','Ownership cost',formatMoney(value))).join('')||empty('Asset-linked costs will appear here.')}

