async function savePaycheck(event){event.preventDefault();try{const id=$('#paycheckId').value||crypto.randomUUID(),estimate=currentPayEstimate(),actualNet=optionalMoney($('#actualNet').value),status=actualNet==null?'estimated':'reconciled';const paycheck=await saveRow('paychecks',{id,income_source_id:$('#paycheckSource').value,period_start:$('#payPeriodStart').value,period_end:$('#payPeriodEnd').value,pay_date:$('#payDate').value,status,estimated_gross_minor:estimate.grossMinor,estimated_pre_tax_minor:parseZero($('#payPreTax').value),estimated_federal_minor:estimate.federalMinor,estimated_state_minor:estimate.stateMinor,estimated_social_security_minor:estimate.socialSecurityMinor,estimated_medicare_minor:estimate.medicareMinor,estimated_post_tax_minor:parseZero($('#payPostTax').value),estimated_retirement_minor:parseZero($('#payRetirement').value),estimated_benefits_minor:parseZero($('#payBenefits').value),estimated_net_minor:estimate.netMinor,actual_gross_minor:optionalMoney($('#actualGross').value),actual_federal_minor:optionalMoney($('#actualFederal').value),actual_state_minor:optionalMoney($('#actualState').value),actual_social_security_minor:optionalMoney($('#actualSocialSecurity').value),actual_medicare_minor:optionalMoney($('#actualMedicare').value),actual_retirement_minor:optionalMoney($('#actualRetirement').value),employer_retirement_minor:optionalMoney($('#actualEmployerRetirement').value),actual_benefits_minor:optionalMoney($('#actualBenefits').value),actual_other_deductions_minor:optionalMoney($('#actualOther').value),actual_net_minor:actualNet,notes:''});if(status==='reconciled'){const amount=reconciledPay(paycheck).netMinor,existing=state.transactions.find(x=>x.paycheck_id===id);await saveRow('transactions',{id:existing?.id||crypto.randomUUID(),transaction_type:'income',amount_minor:amount,description:`${sourceName(paycheck.income_source_id)} paycheck`,transaction_date:paycheck.pay_date,category_id:state.categories.find(x=>x.category_type==='income'&&!x.parent_id)?.id||null,asset_id:null,income_source_id:paycheck.income_source_id,paycheck_id:id,bill_id:null,bill_due_date:null,notes:'Actual reconciled net pay'})}event.target.reset();$('#paycheckId').value='';setDefaultDates();renderAll()}catch{alert('Paycheck could not be saved. Check the period, source, amounts, and actual net value.')}}
