async function handleDelegatedChange(event){if(event.target.matches('[data-budget-category]')){try{const categoryId=event.target.dataset.budgetCategory,month=$('#budgetMonth').value,existing=state.budgets.find(x=>x.category_id===categoryId&&String(x.budget_month).startsWith(month));await saveRow('budgets',{id:existing?.id||crypto.randomUUID(),category_id:categoryId,budget_month:`${month}-01`,amount_minor:parseZero(event.target.value)});renderAll()}catch{alert('Budget amount could not be saved.')}}}
async function handleDelegatedClick(event){const goTo=event.target.closest('[data-go-to]');if(goTo){settingsModalClose();showView(goTo.dataset.goTo);return}const button=event.target.closest('[data-action]');if(!button)return;const{id,action}=button.dataset;try{
  if(action==='edit-category')fillCategory(state.categories.find(x=>x.id===id));
  if(action==='delete-category'&&confirm('Delete this category? Categories in use must be reassigned first.')){await removeRow('categories',id);renderAll()}
  if(action==='move-category-up'){const item=state.categories.find(x=>x.id===id);await saveRow('categories',{...item,sort_order:Math.max(0,item.sort_order-11)});renderAll()}
  if(action==='edit-transaction')fillTransaction(state.transactions.find(x=>x.id===id));
  if(action==='delete-transaction'&&confirm('Delete this transaction permanently?')){await removeRow('transactions',id);renderAll()}
  if(action==='edit-bill')fillBill(state.bills.find(x=>x.id===id));
  if(action==='delete-bill'&&confirm('Delete this bill? Recorded transactions remain.')){await removeRow('bills',id);renderAll()}
  if(action==='record-bill')await recordBill(state.bills.find(x=>x.id===id));
  if(action==='edit-income-source')fillIncomeSource(state.incomeSources.find(x=>x.id===id));
  if(action==='delete-income-source'&&confirm('Delete this income source? Sources with work or paychecks must remain.')){await removeRow('incomeSources',id);renderAll()}
  if(action==='delete-work'&&confirm('Delete this work entry?')){await removeRow('workEntries',id);renderAll()}
  if(action==='edit-paycheck')fillPaycheck(state.paychecks.find(x=>x.id===id));
  if(action==='delete-paycheck'&&confirm('Delete this paycheck? Delete its linked income transaction first if present.')){await removeRow('paychecks',id);renderAll()}
  if(action==='edit-savings')fillSavings(state.savingsGoals.find(x=>x.id===id));
  if(action==='delete-savings'&&confirm('Delete this savings goal?')){await removeRow('savingsGoals',id);renderAll()}
  if(action==='delete-retirement-account'&&confirm('Delete this retirement account?')){await removeRow('retirementAccounts',id);renderAll()}
  if(action==='delete-allocation'&&confirm('Delete this allocation target?')){await removeRow('allocations',id);renderAll()}
  if(action==='edit-asset')fillAsset(state.assets.find(x=>x.id===id));
  if(action==='delete-asset'&&confirm('Delete this asset? Assets referenced by transactions must remain.')){await removeRow('assets',id);renderAll()}
}catch{alert('That change could not be completed. Related records may need to be removed or reassigned first.')}}

async function recordBill(bill){if(!bill)return;const existing=state.transactions.find(x=>x.bill_id===bill.id&&x.bill_due_date===bill.next_due_date);if(existing)return alert('This bill occurrence is already recorded.');const due=bill.next_due_date;await saveRow('transactions',{id:crypto.randomUUID(),transaction_type:'expense',amount_minor:Number(bill.amount_minor),description:bill.name,transaction_date:due,category_id:bill.category_id,asset_id:null,income_source_id:null,paycheck_id:null,bill_id:bill.id,bill_due_date:due,notes:`Recorded from ${bill.frequency} bill`});await saveRow('bills',{...bill,last_materialized_due_date:due,next_due_date:nextBillDate(bill,due)});renderAll()}
function nextBillDate(bill,value){const date=new Date(`${value}T00:00:00Z`),days={weekly:7,biweekly:14,custom:Number(bill.custom_interval_days||1)};if(days[bill.frequency])date.setUTCDate(date.getUTCDate()+days[bill.frequency]);else date.setUTCMonth(date.getUTCMonth()+({monthly:1,quarterly:3,semiannual:6,annual:12}[bill.frequency]||1));return date.toISOString().slice(0,10)}

function fillCategory(item){if(!item)return;showView('budget');$('#categoryId').value=item.id;$('#categoryName').value=item.name;$('#categoryParent').value=item.parent_id||'';$('#categoryType').value=item.category_type;$('#categoryClassification').value=item.classification||'';$('#categoryName').focus()}
function fillTransaction(item){if(!item)return;showView('transactions');$('#transactionId').value=item.id;$('#transactionType').value=item.transaction_type;$('#transactionAmount').value=(item.amount_minor/100).toFixed(2);$('#transactionDescription').value=item.description;$('#transactionDate').value=item.transaction_date;$('#transactionCategory').value=item.category_id||'';$('#transactionAsset').value=item.asset_id||'';$('#transactionIncomeSource').value=item.income_source_id||'';$('#transactionNotes').value=item.notes||''}
function fillBill(item){if(!item)return;showView('bills');$('#billId').value=item.id;$('#billName').value=item.name;$('#billAmount').value=(item.amount_minor/100).toFixed(2);$('#billCategory').value=item.category_id||'';$('#billDate').value=item.next_due_date;$('#billFrequency').value=item.frequency;$('#billCustomDays').value=item.custom_interval_days||'';$('#billClassification').value=item.classification;$('#billActive').checked=item.active;$('#billNotes').value=item.notes||''}
function fillIncomeSource(item){if(!item)return;showView('earnings');$('#incomeSourceId').value=item.id;$('#incomeSourceName').value=item.name;$('#incomeSourceType').value=item.income_type;$('#incomeHourlyRate').value=item.hourly_rate_minor==null?'':(item.hourly_rate_minor/100).toFixed(2);$('#incomeExpectedHours').value=item.standard_weekly_minutes==null?'':item.standard_weekly_minutes/60;$('#incomeSalary').value=item.annual_salary_minor==null?'':(item.annual_salary_minor/100).toFixed(2);$('#incomeFrequency').value=item.pay_frequency;$('#incomeOvertime').value=item.overtime_multiplier_basis_points/10000;updateIncomeSourceExperience();$('#incomeSourceName').focus()}
function fillPaycheck(item){if(!item)return;showView('earnings');$('#paycheckId').value=item.id;$('#paycheckSource').value=item.income_source_id;$('#payPeriodStart').value=item.period_start;$('#payPeriodEnd').value=item.period_end;$('#payDate').value=item.pay_date;$('#payGross').value=(item.estimated_gross_minor/100).toFixed(2);$('#payPreTax').value=(item.estimated_pre_tax_minor/100).toFixed(2);$('#payRetirement').value=(item.estimated_retirement_minor/100).toFixed(2);$('#payBenefits').value=(item.estimated_benefits_minor/100).toFixed(2);$('#payPostTax').value=(item.estimated_post_tax_minor/100).toFixed(2);const fields={actualGross:'actual_gross_minor',actualNet:'actual_net_minor',actualFederal:'actual_federal_minor',actualState:'actual_state_minor',actualSocialSecurity:'actual_social_security_minor',actualMedicare:'actual_medicare_minor',actualRetirement:'actual_retirement_minor',actualEmployerRetirement:'employer_retirement_minor',actualBenefits:'actual_benefits_minor',actualOther:'actual_other_deductions_minor'};Object.entries(fields).forEach(([id,key])=>$(`#${id}`).value=item[key]==null?'':(item[key]/100).toFixed(2));updatePayEstimate()}
function fillSavings(item){if(!item)return;$('#savingsId').value=item.id;$('#savingsName').value=item.name;$('#savingsCurrent').value=(item.current_minor/100).toFixed(2);$('#savingsTarget').value=(item.target_minor/100).toFixed(2);$('#savingsMonthly').value=(item.monthly_contribution_minor/100).toFixed(2);$('#savingsDate').value=item.target_date||'';$('#savingsNotes').value=item.notes||''}
function fillAsset(item){if(!item)return;$('#assetId').value=item.id;$('#assetName').value=item.name;$('#assetGroup').value=item.asset_group;$('#assetType').value=item.asset_type;$('#assetValue').value=(item.current_value_minor/100).toFixed(2);$('#assetPurchaseDate').value=item.purchase_date||'';$('#assetPurchasePrice').value=item.purchase_price_minor==null?'':(item.purchase_price_minor/100).toFixed(2);$('#assetNotes').value=item.notes||''}
function fillRetirementForm(item,force=true){if(!force&&$('#retirementForm').dataset.loaded===item.id)return;$('#retirementForm').dataset.loaded=item.id;$('#retCurrentAge').value=item.current_age;$('#retirementAge').value=item.retirement_age;$('#retIncome').value=(item.annual_income_minor/100).toFixed(2);$('#retContribution').value=item.employee_contribution_basis_points/100;$('#retMatch').value=item.employer_match_basis_points/100;$('#retMatchLimit').value=item.employer_match_limit_basis_points/100;$('#retAdditional').value=(item.additional_annual_minor/100).toFixed(2);$('#retReturn').value=item.expected_return_basis_points/100;$('#retInflation').value=(item.inflation_basis_points||0)/100}

function currentPayEstimate(){return paycheckEstimate({grossMinor:parseZero($('#payGross').value),preTaxMinor:parseZero($('#payPreTax').value),retirementMinor:parseZero($('#payRetirement').value),benefitsMinor:parseZero($('#payBenefits').value),federalBasisPoints:Math.round(Number($('#payFederalRate').value||0)*100),stateBasisPoints:Math.round(Number($('#payStateRate').value||0)*100),postTaxMinor:parseZero($('#payPostTax').value)})}
function updatePayEstimate(){try{const value=currentPayEstimate();$('#payEstimate').textContent=`Estimated take-home: ${formatMoney(value.netMinor)} · deductions ${formatMoney(value.deductionsMinor)}`}catch{$('#payEstimate').textContent='Estimated take-home: —'}}
function updateWorkEstimate(){const source=state.incomeSources.find(x=>x.id===$('#workSource').value);if(!source||source.hourly_rate_minor==null)return $('#workEstimate').textContent='Choose an hourly source.';const regular=Math.round(Number($('#workRegular').value||0)*60),overtime=Math.round(Number($('#workOvertime').value||0)*60);$('#workEstimate').textContent=`Estimated gross: ${formatMoney(hourlyGross(source.hourly_rate_minor,regular,overtime,source.overtime_multiplier_basis_points))}`}
function sourceExpectedMonthly(item){if(item.hourly_rate_minor!=null&&item.standard_weekly_minutes)return Math.round(Number(item.hourly_rate_minor)*Number(item.standard_weekly_minutes)*52/60/12);if(item.annual_salary_minor!=null)return Math.round(Number(item.annual_salary_minor)/12);return 0}
function sourceExpectedPaycheck(item){const annual=item.hourly_rate_minor!=null&&item.standard_weekly_minutes?Math.round(Number(item.hourly_rate_minor)*Number(item.standard_weekly_minutes)*52/60):Number(item.annual_salary_minor||0),periods={weekly:52,biweekly:26,semimonthly:24,monthly:12,quarterly:4,annual:1}[item.pay_frequency];return periods?Math.round(annual/periods):0}
function expectedMonthlyIncome(){return state.incomeSources.filter(x=>x.active).reduce((total,item)=>total+sourceExpectedMonthly(item),0)}
function updateIncomeSourceExperience(){const type=$('#incomeSourceType').value,isHourly=type==='hourly';$$('[data-income-field="hourly"],[data-income-field="hours"],[data-income-field="overtime"]').forEach(x=>x.hidden=!isHourly);$$('[data-income-field="annual"]').forEach(x=>x.hidden=isHourly);try{if(isHourly){const rate=parseZero($('#incomeHourlyRate').value),minutes=Math.round(Number($('#incomeExpectedHours').value||0)*60);$('#incomeSourcePreview').innerHTML=rate&&minutes?`<strong>${formatMoney(rate)} / hour</strong><span>≈ ${formatMoney(Math.round(rate*minutes/60))} / week · ≈ ${formatMoney(Math.round(rate*minutes*52/60/12))} / month before deductions</span>`:`<strong>${rate?`${formatMoney(rate)} / hour`:'Add your hourly rate'}</strong><span>Add expected hours or track worked hours to estimate income.</span>`}else{const annual=parseZero($('#incomeSalary').value),frequency=$('#incomeFrequency').value,periods={weekly:52,biweekly:26,semimonthly:24,monthly:12}[frequency];$('#incomeSourcePreview').innerHTML=annual?`<strong>${formatMoney(annual)} / year</strong><span>≈ ${formatMoney(Math.round(annual/12))} / month${periods?` · ≈ ${formatMoney(Math.round(annual/periods))} per paycheck`:''} before deductions</span>`:'Enter an annual amount to see a simple estimate.'}}catch{$('#incomeSourcePreview').textContent='Use a valid positive amount to see an estimate.'}}
function enhanceRetirementDisclosure(){const retirement=$('[data-view="retirement"]'),splits=$$('.split-layout',retirement),form=$('#retirementForm');if(form&&!form.closest('.feature-disclosure')){const details=document.createElement('details');details.className='feature-disclosure retirement-controls';details.innerHTML='<summary><span><b>Explore projection assumptions</b><small>Age, contributions, match, and expected return</small></span><i>Open</i></summary>';form.before(details);details.append(form)}const accountTools=splits[1]?.firstElementChild;if(accountTools&&!accountTools.closest('.feature-disclosure')){const details=document.createElement('details');details.className='feature-disclosure retirement-controls';details.innerHTML='<summary><span><b>Accounts & allocation</b><small>Add accounts and track current versus target allocation</small></span><i>Open</i></summary>';accountTools.before(details);details.append(accountTools)}}
function retirementInput(){return{currentAge:Number($('#retCurrentAge').value||30),retirementAge:Number($('#retirementAge').value||67),annualIncomeMinor:parseZero($('#retIncome').value),currentBalanceMinor:sum(state.retirementAccounts,'current_balance_minor'),employeeBasisPoints:Math.round(Number($('#retContribution').value||0)*100),matchBasisPoints:Math.round(Number($('#retMatch').value||0)*100),matchLimitBasisPoints:Math.round(Number($('#retMatchLimit').value||0)*100),additionalAnnualMinor:parseZero($('#retAdditional').value),returnBasisPoints:Math.round(Number($('#retReturn').value||0)*100)}}
function applyRetirementScenario(value){if(value!=='custom')$('#retContribution').value=Number(value)/100;renderRetirement()}

function loadSettings(){try{const saved=JSON.parse(localStorage.getItem(SETTINGS_KEY)||'{}');return{theme:THEMES.includes(saved.theme)?saved.theme:'classic',density:saved.density==='compact'?'compact':'comfortable',onboardingDismissed:saved.onboardingDismissed===true}}catch{return{...DEFAULT_SETTINGS}}}
function applySettings(){document.documentElement.dataset.theme=settings.theme;document.documentElement.dataset.density=settings.density;const colors={classic:'#183b35',ledger:'#493c2d',clear:'#183b4d',vault:'#050f0c',market:'#050607'};$('#themeColor').content=colors[settings.theme]}
function persistSettings(){localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings))}
function openSettings(){showSettingsPanel('main',false);$('#settingsEmail').textContent=currentUser?.email||'Signed-in account';$$('input[name="money-theme"]').forEach(x=>x.checked=x.value===settings.theme);$$('input[name="money-density"]').forEach(x=>x.checked=x.value===settings.density);$('#settingsModal').showModal();setTimeout(()=>$('[data-settings-open]',$('#settingsModal'))?.focus(),0)}
function showSettingsPanel(name,focus=true){$$('[data-settings-panel]',$('#settingsModal')).forEach(x=>x.classList.toggle('active',x.dataset.settingsPanel===name));if(focus)setTimeout(()=>(name==='main'?$('[data-settings-open]',$('#settingsModal')):$('[data-settings-back]',$('#settingsModal')))?.focus(),0)}
function saveSettingsControls(){settings={...settings,theme:$('input[name="money-theme"]:checked')?.value||settings.theme,density:$('input[name="money-density"]:checked')?.value||settings.density};persistSettings();applySettings()}
function settingsModalClose(){if($('#settingsModal').open)$('#settingsModal').close()}
function runQuickAction(action){const destinations={income:'transactions',expense:'transactions',bill:'bills',savings:'savings'};showView(destinations[action]);if(action==='income'||action==='expense'){$('#transactionType').value=action;$('#transactionAmount').focus()}else if(action==='bill')$('#billName').focus();else $('#savingsName').focus()}
function hasMeaningfulMoneyData(){return ['budgets','assets','incomeSources','workEntries','paychecks','transactions','bills','savingsGoals','contributions','retirementProfiles','retirementAccounts','allocations','snapshots'].some(key=>state[key].length>0)}
function maybeOpenOnboarding(){if(settings.onboardingDismissed||hasMeaningfulMoneyData())return;setTimeout(()=>{if(!$('#onboardingModal').open){showOnboardingStep(1);$('#onboardingModal').showModal()}},350)}
function showOnboardingStep(step){onboardingStep=Math.max(1,Math.min(4,step));$$('[data-onboarding-step]').forEach(x=>x.classList.toggle('active',Number(x.dataset.onboardingStep)===onboardingStep));$('#onboardingStepLabel').textContent=`Step ${onboardingStep} of 4`;$('.onboarding-progress i').style.width=`${onboardingStep*25}%`;$('#onboardingBack').hidden=onboardingStep===1;$('#onboardingNext').textContent=onboardingStep===4?'Finish setup':'Continue'}
function onboardingType(){return $('input[name="onboarding-income-type"]:checked')?.value||'salary'}
function updateOnboardingFields(){const type=onboardingType(),hourly=type==='hourly';$('#onboardingAmountLabel').childNodes[0].nodeValue=hourly?'Hourly rate':'Annual amount';$('#onboardingHoursField').hidden=!hourly;updateOnboardingPreview()}
function updateOnboardingPreview(){try{const amount=parseZero($('#onboardingIncomeAmount').value),type=onboardingType(),hours=Number($('#onboardingHours').value||0);if(!amount)return $('#onboardingPreview').textContent='Add an amount to preview your expected income.';if(type==='hourly')$('#onboardingPreview').innerHTML=hours?`<strong>${formatMoney(amount)} / hour</strong><span>≈ ${formatMoney(Math.round(amount*hours))} / week · ≈ ${formatMoney(Math.round(amount*hours*52/12))} / month</span>`:`<strong>${formatMoney(amount)} / hour</strong><span>Add expected hours later or track the hours you actually work.</span>`;else $('#onboardingPreview').innerHTML=`<strong>${formatMoney(amount)} / year</strong><span>≈ ${formatMoney(Math.round(amount/12))} / month before deductions</span>`}catch{$('#onboardingPreview').textContent='Enter a valid amount to continue.'}}
async function advanceOnboarding(){if(onboardingStep<4)return showOnboardingStep(onboardingStep+1);$('#onboardingNext').disabled=true;try{const type=onboardingType(),amount=optionalMoney($('#onboardingIncomeAmount').value),name=$('#onboardingIncomeName').value.trim(),frequency=$('input[name="onboarding-frequency"]:checked')?.value||'biweekly',hours=Number($('#onboardingHours').value||0);if(name&&amount){await saveRow('incomeSources',{id:crypto.randomUUID(),name,income_type:type,hourly_rate_minor:type==='hourly'?amount:null,annual_salary_minor:type==='hourly'?null:amount,pay_frequency:frequency,standard_weekly_minutes:type==='hourly'&&hours?Math.round(hours*60):null,overtime_multiplier_basis_points:15000,notes:'',active:true})}for(const input of $$('[data-starter-bill]')){const billAmount=optionalMoney(input.value);if(!billAmount)continue;const name=input.dataset.starterBill,category=state.categories.find(x=>x.category_type==='expense'&&(x.name===name||name.toLowerCase().includes(x.name.toLowerCase())||x.name.toLowerCase().includes(name.split(' ')[0].toLowerCase())));await saveRow('bills',{id:crypto.randomUUID(),name,amount_minor:billAmount,category_id:category?.id||null,next_due_date:today(),frequency:'monthly',custom_interval_days:null,classification:'fixed',notes:'Added during setup',active:true,last_materialized_due_date:null})}settings.onboardingDismissed=true;persistSettings();$('#onboardingModal').close();populateControls();renderAll()}catch{alert('Setup could not be saved. Check the amounts or skip and add these items later.')}finally{$('#onboardingNext').disabled=false}}
function dismissOnboarding(){settings.onboardingDismissed=true;persistSettings();$('#onboardingModal').close()}
async function resetMoney(){if(!confirm('Permanently delete every Money record in this account? This cannot be undone.'))return;if(prompt('Type RESET MONEY to confirm')!=='RESET MONEY')return;const order=['contributions','transactions','workEntries','paychecks','budgets','bills','allocations','retirementAccounts','retirementProfiles','snapshots','savingsGoals','assets','incomeSources','categories'];try{for(const key of order){const{error}=await client.from(TABLES[key]).delete().eq('user_id',currentUser.id);if(error)throw error}state=Object.fromEntries(Object.keys(TABLES).map(key=>[key,[]]));await seedCategories();settingsModalClose();populateControls();renderAll()}catch{alert('Money data could not be reset. No further deletes were attempted after the failure.')}}

function reportBounds(range){const end=today();if(range==='custom')return{start:$('#reportStart').value||end,end:$('#reportEnd').value||end};const now=new Date(`${end}T00:00:00Z`),start=new Date(now);if(range==='month')start.setUTCDate(1);if(range==='3m')start.setUTCMonth(start.getUTCMonth()-3);if(range==='6m')start.setUTCMonth(start.getUTCMonth()-6);if(range==='1y')start.setUTCFullYear(start.getUTCFullYear()-1);if(range==='ytd')start.setUTCMonth(0,1);return{start:start.toISOString().slice(0,10),end}}
function monthlyBillAmount(item){const amount=Number(item.amount_minor);return Math.round(amount*({weekly:52/12,biweekly:26/12,monthly:1,quarterly:1/3,semiannual:1/6,annual:1/12,custom:30/Number(item.custom_interval_days||30)}[item.frequency]||1))}
function setDefaultDates(){const date=today(),month=monthKey();['transactionDate','billDate','workDate','payDate','contributionDate','reportStart','reportEnd'].forEach(id=>{if($(`#${id}`)&&!$(`#${id}`).value)$(`#${id}`).value=date});if(!$('#payPeriodStart').value)$('#payPeriodStart').value=date;if(!$('#payPeriodEnd').value)$('#payPeriodEnd').value=date;if(!$('#overviewMonth').value)$('#overviewMonth').value=month;if(!$('#budgetMonth').value)$('#budgetMonth').value=month}
function sourceName(id){return state.incomeSources.find(x=>x.id===id)?.name||'Income source'}
function humanFrequency(value){return({weekly:'Weekly',biweekly:'Every two weeks',semimonthly:'Twice monthly',monthly:'Monthly',quarterly:'Quarterly',semiannual:'Twice a year',annual:'Annual',irregular:'Flexible',custom:'Custom'}[value]||value)}
function categoryIcon(name){const value=name.toLowerCase();if(/home|housing|rent|mortgage/.test(value))return'⌂';if(/food|grocery|restaurant|coffee/.test(value))return'◉';if(/transport|gas|car|parking/.test(value))return'↗';if(/bill|utilit|subscription/.test(value))return'◷';if(/health|medical/.test(value))return'✚';if(/saving/.test(value))return'◇';if(/entertain/.test(value))return'▷';if(/shop/.test(value))return'□';return'•'}
function parsePositive(value){const amount=parseMoney(value);if(amount<=0)throw TypeError();return amount}function parseZero(value){if(String(value??'').trim()==='')return 0;const amount=parseMoney(value);if(amount<0)throw TypeError();return amount}function optionalMoney(value){return String(value??'').trim()===''?null:parseZero(value)}
function sum(items,key){return items.reduce((total,item)=>total+Number(item[key]||0),0)}function sortOrder(a,b){return a.sort_order-b.sort_order||a.name.localeCompare(b.name)}function today(){return new Date().toISOString().slice(0,10)}
function formatHours(minutes){const value=Number(minutes||0)/60;return`${Math.round(value*100)/100} hour${value===1?'':'s'}`}
function statCard(label,value,detail,highlight=false){return`<article class="stat-card${highlight?' highlight':''}"><span>${escapeHtml(label)}</span><strong>${formatMoney(value)}</strong><small>${escapeHtml(detail)}</small></article>`}
function simpleRow(title,detail,value){return`<div class="list-row"><div><h3>${escapeHtml(title)}</h3><p>${escapeHtml(detail)}</p></div><strong>${escapeHtml(value)}</strong></div>`}
function empty(message){return`<div class="empty">${escapeHtml(message)}</div>`}
function friendlyEmpty(title,message,actionLabel,view){return`<div class="empty friendly-empty"><span aria-hidden="true">◇</span><h3>${escapeHtml(title)}</h3><p>${escapeHtml(message)}</p><button class="button secondary" data-go-to="${view}">${escapeHtml(actionLabel)}</button></div>`}
function bar(label,value,max){return`<div class="bar-column" title="${escapeHtml(label)}: ${formatMoney(value)}"><i style="height:${Math.max(3,Math.round(value/max*150))}px"></i><span>${escapeHtml(label)}</span></div>`}
function lineChart(values){if(!values.length)return empty('No projection data.');const width=600,height=180,pad=10,max=Math.max(1,...values),min=Math.min(0,...values),span=Math.max(1,max-min),points=values.map((value,index)=>`${pad+index*(width-pad*2)/Math.max(1,values.length-1)},${height-pad-(value-min)/span*(height-pad*2)}`).join(' ');return`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Projection chart"><line class="grid" x1="${pad}" y1="${height-pad}" x2="${width-pad}" y2="${height-pad}"></line><polyline points="${points}"></polyline></svg>`}
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]))}
function setCloud(message,error=false){$('#cloudStatus').textContent=message;$('#cloudStatus').classList.toggle('error',error)}
function isSchemaError(error){const code=String(error?.code||'');const message=String(error?.message||'');return ['42P01','42703','PGRST204','PGRST205'].includes(code)||/relation .* does not exist|column .* does not exist|schema cache/i.test(message)}
function showLoadError(error){const schema=isSchemaError(error);console.error('Money cloud load failed.',{code:error?.code||'unknown',kind:schema?'schema':'connection'});$('#loadNoticeText').textContent=schema?'Money needs its database migration before private records can load.':'Money could not reach your private cloud records. Your data was not changed.';$('#loadNotice').hidden=false}
function hideLoadNotice(){$('#loadNotice').hidden=true}
